<?php
require_once __DIR__.'/../../portal_options.php';
$cats=$db->query('SELECT c.*, (SELECT COUNT(*) FROM articles a WHERE a.category_id=c.id) AS total FROM categories c ORDER BY sort_order,name')->fetchAll();
$active=array_map('intval',array_column(igua_portal_active_categories($cats,setting('portal_active_categories','')),'id'));
?>
<div class="panel"><h2>Categorias do portal</h2><p class="muted">Ative somente as categorias usadas no menu e em novas matérias. As antigas continuam no acervo e suas URLs são mantidas.</p>
<form method="post" action="<?=h(admin_link('portal_local_preset'))?>"><?=csrf_field()?><button class="btn outline" data-confirm="Aplicar Iguatama, Região, Minas Gerais, Brasil e Mundo? As configurações da home serão redefinidas. As matérias anteriores não serão excluídas nem reclassificadas automaticamente.">Aplicar modelo Iguatama Online</button></form>
<form method="post" action="<?=h(admin_link('portal_category_selection'))?>"><?=csrf_field()?>
<fieldset class="home-settings-categories"><legend>Categorias ativas</legend><?php foreach($cats as $c):?><label><input type="checkbox" name="active_categories[]" value="<?=(int)$c['id']?>" <?=in_array((int)$c['id'],$active,true)?'checked':''?>> <?=h($c['name'])?> (<?=(int)$c['total']?>)</label><?php endforeach;?></fieldset><button class="btn primary">Salvar categorias ativas</button></form></div>
<div class="panel" id="new-category"><h2>Nova categoria</h2><form method="post" action="<?=h(admin_link('save_category'))?>" class="inline-form"><?=csrf_field()?><input name="name" required maxlength="75" placeholder="Nome da categoria"><button class="btn primary">Adicionar</button></form></div>
<div class="panel"><h2>Reclassificar acervo</h2><p class="muted">Mova as matérias de uma categoria para outra somente se todas tiverem a mesma abrangência. Categorias misturadas devem ser revistas matéria por matéria. A categoria antiga permanece como referência histórica.</p><form method="post" action="<?=h(admin_link('portal_category_move'))?>"><?=csrf_field()?><div class="form-grid"><label>De<select name="from" required><option value="">Selecione</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=h($c['name'])?> (<?=(int)$c['total']?>)</option><?php endforeach;?></select></label><label>Para<select name="to" required><option value="">Selecione</option><?php foreach($cats as $c):if(!in_array((int)$c['id'],$active,true))continue;?><option value="<?=(int)$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label></div><button class="btn outline" data-confirm="Reclassificar todas as matérias da categoria selecionada?">Mover matérias</button></form></div>
<div class="panel"><h2>Editar categorias</h2><?php foreach($cats as $c):?><details><summary><?=h($c['name'])?> · <?=(int)$c['total']?> matérias <?=in_array((int)$c['id'],$active,true)?'':'· Arquivada'?></summary><form method="post" action="<?=h(admin_link('save_category'))?>" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$c['id']?>"><label>Nome<input name="name" maxlength="75" required value="<?=h($c['name'])?>"></label><label>Ordem<input name="sort_order" type="number" min="0" max="9999" value="<?=(int)$c['sort_order']?>"></label><small>Endereço preservado: /<?=h($c['slug'])?></small><button class="btn outline">Salvar nome e ordem</button></form></details><?php endforeach;?></div>
